using Nethereum.ABI.FunctionEncoding.Attributes;
using Nethereum.Contracts;
using System.Numerics;

namespace Nethereum.X402.IntegrationTests.Helpers;

[Function("MockUSDC", "constructor")]
public class MockUSDCDeployment : ContractDeploymentMessage
{
    public static string BYTECODE =
        "";

    public MockUSDCDeployment() : base(BYTECODE) { }

    [Parameter("string", "_name", 1)]
    public string TokenName { get; set; } = string.Empty;

    [Parameter("string", "_symbol", 2)]
    public string TokenSymbol { get; set; } = string.Empty;

    [Parameter("uint8", "_decimals", 3)]
    public byte Decimals { get; set; }

    [Parameter("string", "_version", 4)]
    public string Version { get; set; } = string.Empty;
}
